draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  for (let i = 0; i < 10; i++) {
    let x = W/2 + Math.cos(t + i) * 50;
    let y = H/2 + Math.sin(t + i) * 50;
    ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    let x = W/2 + Math.cos(t + i) * 100;
    let y = H/2 + Math.sin(t + i) * 100;
    ctx.beginPath();
    ctx.arc(x, y, 5, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
